=== src/main/java/br/com/marealta/ReservationService.java
     1	package br.com.marealta;
     2	
     3	import br.com.marealta.domain.ConfirmationEmail;
     4	import br.com.marealta.domain.Document;
     5	import br.com.marealta.domain.Message;
     6	import br.com.marealta.domain.OperationNotAllowedException;
     7	import br.com.marealta.domain.Reports;
     8	import br.com.marealta.domain.Reservation;
     9	import br.com.marealta.domain.Room;
    10	import br.com.marealta.domain.Rooms;
    11	import br.com.marealta.persistence.Database;
    12	import br.com.marealta.persistence.MessageRepository;
    13	import br.com.marealta.persistence.ReservationRepository;
    14	
    15	import java.time.LocalDate;
    16	import java.time.YearMonth;
    17	import java.util.List;
    18	import java.util.function.Consumer;
    19	
    20	public final class ReservationService {
    21	    private final Database db;
    22	    private final ReservationRepository reservations = new ReservationRepository();
    23	    private final MessageRepository messages = new MessageRepository();
    24	    /** Garante que duas reservas não disputem a mesma noite. */
    25	    private final Object writeLock = new Object();
    26	
    27	    public ReservationService(Database db) {
    28	        this.db = db;
    29	    }
    30	
    31	    public Reservation create(NewReservation req) {
    32	        synchronized (writeLock) {
    33	            return db.transaction(c -> {
    34	                Room room = Rooms.find(req.roomNumber()).orElseThrow(
    35	                        () -> new ApiException(404, "ROOM_NOT_FOUND", "Quarto não encontrado"));
    36	                if (req.guests() > room.type().capacity()) {
    37	                    throw new ApiException(422, "CAPACITY_EXCEEDED",
    38	                            "O quarto comporta no máximo " + room.type().capacity() + " hóspedes");
    39	                }
    40	                if (reservations.isRoomTaken(c, room.number(), req.checkIn(), req.checkOut())) {
    41	                    throw new ApiException(409, "ROOM_UNAVAILABLE", "Quarto já reservado no período");
    42	                }
    43	                Reservation r = Reservation.create(room, req.guestName(), req.guestEmail(), req.identity(),
    44	                        req.checkIn(), req.checkOut(), req.guests(), req.ratePlan());
    45	                reservations.insert(c, r);
    46	                return r;
    47	            });
    48	        }
    49	    }
    50	
    51	    public Reservation get(long id) {
    52	        return db.transaction(c -> reservations.find(c, id).orElseThrow(ApiException::reservationNotFound));
    53	    }
    54	
    55	    public Reservation confirm(long id) {
    56	        return change(id, Reservation::confirm, (c, r) -> {
    57	            messages.insert(c, ConfirmationEmail.of(r));
    58	        });
    59	    }
    60	
    61	    public Reservation cancel(long id) {
    62	        return change(id, Reservation::cancel, null);
    63	    }
    64	
    65	    public Reservation checkIn(long id) {
    66	        return change(id, Reservation::checkIn, null);
    67	    }
    68	
    69	    public Document checkOut(long id) {
    70	        return change(id, Reservation::checkOut, null).document();
    71	    }
    72	
    73	    public Document document(long id) {
    74	        try {
    75	            return get(id).document();
    76	        } catch (OperationNotAllowedException e) {
    77	            throw notAllowed(e);
    78	        }
    79	    }
    80	
    81	    public List<Message> messages() {
    82	        return db.transaction(messages::all);
    83	    }
    84	
    85	    public String occupancyReport(LocalDate night) {
    86	        return Reports.occupancy(db.transaction(c -> reservations.paidOccupying(c, night)));
    87	    }
    88	
    89	    public String revenueReport(YearMonth month) {
    90	        return Reports.revenue(db.transaction(c -> reservations.startingIn(c, month)));
    91	    }
    92	
    93	    @FunctionalInterface
    94	    private interface AfterChange {
    95	        void run(java.sql.Connection c, Reservation r) throws java.sql.SQLException;
    96	    }
    97	
    98	    private Reservation change(long id, Consumer<Reservation> operation, AfterChange after) {
    99	        synchronized (writeLock) {
   100	            try {
   101	                return db.transaction(c -> {
   102	                    Reservation r = reservations.find(c, id).orElseThrow(ApiException::reservationNotFound);
   103	                    operation.accept(r);
   104	                    reservations.update(c, r);
   105	                    if (after != null) {
   106	                        after.run(c, r);
   107	                    }
   108	                    return r;
   109	                });
   110	            } catch (OperationNotAllowedException e) {
   111	                throw notAllowed(e);
   112	            }
   113	        }
   114	    }
   115	
   116	    private static ApiException notAllowed(OperationNotAllowedException e) {
   117	        return new ApiException(409, "OPERATION_NOT_ALLOWED", e.getMessage());
   118	    }
   119	}
=== src/main/java/br/com/marealta/web/RequestParser.java
     1	package br.com.marealta.web;
     2	
     3	import br.com.marealta.ApiException;
     4	import br.com.marealta.NewReservation;
     5	import br.com.marealta.domain.Identity;
     6	import br.com.marealta.domain.IdentityKinds;
     7	import br.com.marealta.domain.RatePlan;
     8	import com.fasterxml.jackson.core.JsonProcessingException;
     9	import com.fasterxml.jackson.databind.JsonNode;
    10	import com.fasterxml.jackson.databind.ObjectMapper;
    11	
    12	import java.time.LocalDate;
    13	import java.time.YearMonth;
    14	import java.time.format.DateTimeParseException;
    15	import java.util.HashMap;
    16	import java.util.Map;
    17	
    18	final class RequestParser {
    19	    private static final ObjectMapper MAPPER = new ObjectMapper();
    20	
    21	    private RequestParser() {
    22	    }
    23	
    24	    static NewReservation newReservation(String body) {
    25	        JsonNode json;
    26	        try {
    27	            json = MAPPER.readTree(body);
    28	        } catch (JsonProcessingException e) {
    29	            throw ApiException.invalidRequest("Corpo não é um JSON válido");
    30	        }
    31	        if (json == null || !json.isObject()) {
    32	            throw ApiException.invalidRequest("Corpo deve ser um objeto JSON");
    33	        }
    34	        int roomNumber = integer(json, "roomNumber");
    35	        String name = text(json, "guestName");
    36	        String email = text(json, "guestEmail");
    37	        LocalDate checkIn = date(text(json, "checkIn"), "checkIn");
    38	        LocalDate checkOut = date(text(json, "checkOut"), "checkOut");
    39	        int guests = integer(json, "guests");
    40	        RatePlan plan = ratePlan(text(json, "ratePlan"));
    41	        if (!checkOut.isAfter(checkIn)) {
    42	            throw ApiException.invalidRequest("A saída deve ser depois da entrada");
    43	        }
    44	        if (guests < 1) {
    45	            throw ApiException.invalidRequest("É preciso pelo menos um hóspede");
    46	        }
    47	        Identity identity = IdentityKinds.from(identityFields(json)).orElseThrow(() -> ApiException.invalidRequest(
    48	                "Informe guestCpf, ou companyCnpj com companyName, ou guestPassport com guestCountry"));
    49	        return new NewReservation(roomNumber, name, email, identity, checkIn, checkOut, guests, plan);
    50	    }
    51	
    52	    static LocalDate day(String value) {
    53	        if (value == null) {
    54	            throw ApiException.invalidRequest("Parâmetro date é obrigatório");
    55	        }
    56	        return date(value, "date");
    57	    }
    58	
    59	    static YearMonth month(String value) {
    60	        if (value == null) {
    61	            throw ApiException.invalidRequest("Parâmetro month é obrigatório");
    62	        }
    63	        try {
    64	            return YearMonth.parse(value);
    65	        } catch (DateTimeParseException e) {
    66	            throw ApiException.invalidRequest("month deve estar no formato 2027-07");
    67	        }
    68	    }
    69	
    70	    private static Map<String, String> identityFields(JsonNode json) {
    71	        Map<String, String> fields = new HashMap<>();
    72	        for (String f : IdentityKinds.allFields()) {
    73	            JsonNode node = json.get(f);
    74	            if (node == null || node.isNull()) {
    75	                continue;
    76	            }
    77	            if (!node.isTextual()) {
    78	                throw ApiException.invalidRequest("Campo " + f + " deve ser texto");
    79	            }
    80	            fields.put(f, node.asText());
    81	        }
    82	        return fields;
    83	    }
    84	
    85	    private static String text(JsonNode json, String field) {
    86	        JsonNode node = json.get(field);
    87	        if (node == null || !node.isTextual() || node.asText().isBlank()) {
    88	            throw ApiException.invalidRequest("Campo " + field + " é obrigatório");
    89	        }
    90	        return node.asText();
    91	    }
    92	
    93	    private static int integer(JsonNode json, String field) {
    94	        JsonNode node = json.get(field);
    95	        if (node == null || !node.isIntegralNumber() || !node.canConvertToInt()) {
    96	            throw ApiException.invalidRequest("Campo " + field + " deve ser um número inteiro");
    97	        }
    98	        return node.asInt();
    99	    }
   100	
   101	    private static LocalDate date(String value, String field) {
   102	        try {
   103	            return LocalDate.parse(value);
   104	        } catch (DateTimeParseException e) {
   105	            throw ApiException.invalidRequest("Campo " + field + " deve estar no formato 2027-07-10");
   106	        }
   107	    }
   108	
   109	    private static RatePlan ratePlan(String value) {
   110	        try {
   111	            return RatePlan.valueOf(value);
   112	        } catch (IllegalArgumentException e) {
   113	            throw ApiException.invalidRequest("ratePlan deve ser STANDARD ou NON_REFUNDABLE");
   114	        }
   115	    }
   116	}
