    18	    public static Javalin create(ReservationService service) {
    19	        Javalin app = Javalin.create(config -> config.showJavalinBanner = false);
    20	
    21	        app.exception(ApiException.class, (e, ctx) -> error(ctx, e.status(), e.code(), e.getMessage()));
    22	        app.exception(Exception.class, (e, ctx) -> {
    23	            e.printStackTrace();
    24	            error(ctx, 500, "INTERNAL_ERROR", "Erro interno");
    25	        });
    26	
    27	        app.get("/rooms", ctx -> ctx.json(Rooms.all().stream().map(Views::room).toList()));
    28	
    29	        app.post("/reservations", ctx -> {
    30	            var created = service.create(RequestParser.newReservation(ctx.body()));
    31	            ctx.status(201).json(Views.reservation(created));
    32	        });
    33	        app.get("/reservations/{id}", ctx -> ctx.json(Views.reservation(service.get(id(ctx)))));
    34	        app.post("/reservations/{id}/confirmation",
    35	                ctx -> ctx.json(Views.reservation(service.confirm(id(ctx)))));
    36	        app.post("/reservations/{id}/cancellation",
    37	                ctx -> ctx.json(Views.reservation(service.cancel(id(ctx)))));
    38	        app.post("/reservations/{id}/check-in",
    39	                ctx -> ctx.json(Views.reservation(service.checkIn(id(ctx)))));
    40	        app.post("/reservations/{id}/check-out",
    41	                ctx -> ctx.json(Views.document(service.checkOut(id(ctx)))));
    42	        app.get("/reservations/{id}/document",
    43	                ctx -> ctx.json(Views.document(service.document(id(ctx)))));
    44	
    45	        app.get("/messages", ctx -> ctx.json(service.messages().stream().map(Views::message).toList()));
    46	
    47	        app.get("/reports/occupancy", ctx -> ctx.contentType(CSV)
    48	                .result(service.occupancyReport(RequestParser.day(ctx.queryParam("date")))));
    49	        app.get("/reports/revenue", ctx -> ctx.contentType(CSV)
    50	                .result(service.revenueReport(RequestParser.month(ctx.queryParam("month")))));
    51	        return app;
    52	    }
