     1	package br.com.marealta.domain;
     2	
     3	import java.util.List;
     4	import java.util.Map;
     5	import java.util.Optional;
     6	
     7	/** Registro dos jeitos de se identificar. Um novo jeito entra aqui, e só aqui. */
     8	public final class IdentityKinds {
     9	    private static final List<IdentityKind> KINDS = List.of(
    10	            CpfIdentity.KIND,
    11	            CnpjIdentity.KIND,
    12	            PassportIdentity.KIND);
    13	
    14	    private IdentityKinds() {
    15	    }
    16	
    17	    /** Todos os campos de identificação, na ordem em que aparecem na API. */
    18	    public static List<String> allFields() {
    19	        return KINDS.stream().flatMap(k -> k.fields().stream()).toList();
    20	    }
    21	
    22	    /**
    23	     * Monta a identificação a partir dos campos informados (nulos ou ausentes não contam).
    24	     * Vazio se não for exatamente um jeito completo.
    25	     */
    26	    public static Optional<Identity> from(Map<String, String> given) {
    27	        List<IdentityKind> used = KINDS.stream()
    28	                .filter(k -> k.fields().stream().anyMatch(f -> isPresent(given, f)))
    29	                .toList();
    30	        if (used.size() != 1) {
    31	            return Optional.empty();
    32	        }
    33	        IdentityKind kind = used.get(0);
    34	        if (!kind.fields().stream().allMatch(f -> isPresent(given, f))) {
    35	            return Optional.empty();
    36	        }
    37	        return Optional.of(kind.factory().apply(given));
    38	    }
    39	
    40	    private static boolean isPresent(Map<String, String> given, String field) {
    41	        String value = given.get(field);
    42	        return value != null && !value.isBlank();
    43	    }
    44	}
