     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	
     6	public record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
     7	    private static final BigDecimal HIGH_SEASON_FACTOR = new BigDecimal("1.20");
     8	
     9	    public static Quote of(RoomType type, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    10	        BigDecimal subtotal = Money.round(BigDecimal.ZERO);
    11	        int nights = 0;
    12	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    13	            subtotal = subtotal.add(nightPrice(type, night));
    14	            nights++;
    15	        }
    16	        BigDecimal discount = plan.discount(subtotal);
    17	        return new Quote(nights, subtotal, discount, subtotal.subtract(discount));
    18	    }
    19	
    20	    static BigDecimal nightPrice(RoomType type, LocalDate night) {
    21	        BigDecimal rate = type.nightlyRate();
    22	        return Money.round(isHighSeason(night) ? rate.multiply(HIGH_SEASON_FACTOR) : rate);
    23	    }
    24	
    25	    static boolean isHighSeason(LocalDate night) {
    26	        int month = night.getMonthValue();
    27	        return month == 1 || month == 2 || month == 7 || (month == 12 && night.getDayOfMonth() >= 15);
    28	    }
    29	}
