     5	import java.sql.Connection;
     6	import java.sql.DriverManager;
     7	import java.sql.SQLException;
     8	import java.sql.Statement;
     9	import java.util.stream.Collectors;
    10	
    11	public final class Database {
    12	    @FunctionalInterface
    13	    public interface Work<T> {
    14	        T run(Connection connection) throws SQLException;
    15	    }
    16	
    17	    private final String url;
    18	    private final String user;
    19	    private final String password;
    20	
    21	    public Database(String url, String user, String password) {
    22	        this.url = url;
    23	        this.user = user;
    24	        this.password = password;
    25	    }
    26	
    27	    public <T> T transaction(Work<T> work) {
    28	        try (Connection c = DriverManager.getConnection(url, user, password)) {
    29	            c.setAutoCommit(false);
    30	            try {
    31	                T result = work.run(c);
    32	                c.commit();
    33	                return result;
    34	            } catch (SQLException | RuntimeException e) {
    35	                c.rollback();
    36	                throw e;
    37	            }
    38	        } catch (SQLException e) {
    39	            throw new IllegalStateException("Erro de banco de dados", e);
    40	        }
    41	    }
    42	
    43	    /** Cria o que falta no banco; espera o banco ficar disponível. */
    44	    public void initialize() {
    45	        long deadline = System.currentTimeMillis() + 60_000;
    46	        while (true) {
    47	            try {
    48	                createSchema();
    49	                return;
    50	            } catch (RuntimeException e) {
    51	                if (System.currentTimeMillis() > deadline) {
    52	                    throw e;
    53	                }
    54	                try {
    55	                    Thread.sleep(1000);
    56	                } catch (InterruptedException ie) {
    57	                    Thread.currentThread().interrupt();
    58	                    throw e;
    59	                }
    60	            }
    61	        }
    62	    }
    63	
    64	    private void createSchema() {
    65	        String identityColumns = IdentityKinds.allFields().stream()
    66	                .map(f -> f + " text")
    67	                .collect(Collectors.joining(", "));
    68	        transaction(c -> {
    69	            try (Statement s = c.createStatement()) {
    70	                s.execute("select pg_advisory_xact_lock(7070)");
    71	                s.execute("create table if not exists reservations ("
    72	                        + "id bigserial primary key, room_number int not null, "
    73	                        + "guest_name text not null, guest_email text not null, "
    74	                        + identityColumns + ", "
    75	                        + "check_in date not null, check_out date not null, guests int not null, "
    76	                        + "rate_plan text not null, nights int not null, "
    77	                        + "subtotal numeric(12,2) not null, discount numeric(12,2) not null, "
    78	                        + "total numeric(12,2) not null, status text not null, "
    79	                        + "amount_paid numeric(12,2) not null, refund numeric(12,2))");
    80	                s.execute("create table if not exists messages ("
    81	                        + "id bigserial primary key, channel text not null, recipient text not null, "
    82	                        + "subject text not null, body text not null)");
    83	            }
    84	            return null;
    85	        });
    86	    }
    87	}
