    26	public final class ReservationRepository {
    27	
    28	    public void insert(Connection c, Reservation r) throws SQLException {
    29	        List<String> identityFields = IdentityKinds.allFields();
    30	        String sql = "insert into reservations (room_number, guest_name, guest_email, "
    31	                + String.join(", ", identityFields)
    32	                + ", check_in, check_out, guests, rate_plan, nights, subtotal, discount, total, status, "
    33	                + "amount_paid, refund) values (?, ?, ?, "
    34	                + identityFields.stream().map(f -> "?").collect(Collectors.joining(", "))
    35	                + ", ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)";
    36	        try (PreparedStatement st = c.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
    37	            int i = 1;
    38	            st.setInt(i++, r.room().number());
    39	            st.setString(i++, r.guestName());
    40	            st.setString(i++, r.guestEmail());
    41	            Map<String, String> fields = r.identity().fields();
    42	            for (String f : identityFields) {
    43	                st.setString(i++, fields.get(f));
    44	            }
    45	            st.setObject(i++, r.checkInDate());
    46	            st.setObject(i++, r.checkOutDate());
    47	            st.setInt(i++, r.guests());
    48	            st.setString(i++, r.ratePlan().name());
    49	            st.setInt(i++, r.quote().nights());
    50	            st.setBigDecimal(i++, r.quote().subtotal());
    51	            st.setBigDecimal(i++, r.quote().discount());
    52	            st.setBigDecimal(i++, r.quote().total());
    53	            st.setString(i++, r.status().name());
    54	            st.setBigDecimal(i++, r.amountPaid());
    55	            st.setBigDecimal(i, r.refund());
    56	            st.executeUpdate();
    57	            try (ResultSet keys = st.getGeneratedKeys()) {
    58	                keys.next();
    59	                r.assignId(keys.getLong("id"));
    60	            }
    61	        }
    62	    }
    63	
    64	    public void update(Connection c, Reservation r) throws SQLException {
    65	        try (PreparedStatement st = c.prepareStatement(
    66	                "update reservations set status = ?, amount_paid = ?, refund = ? where id = ?")) {
    67	            st.setString(1, r.status().name());
    68	            st.setBigDecimal(2, r.amountPaid());
    69	            st.setBigDecimal(3, r.refund());
    70	            st.setLong(4, r.id());
    71	            st.executeUpdate();
    72	        }
    73	    }
    74	
    75	    public Optional<Reservation> find(Connection c, long id) throws SQLException {
    76	        return query(c, "select * from reservations where id = ?", st -> st.setLong(1, id)).stream().findFirst();
    77	    }
    78	
    79	    public boolean isRoomTaken(Connection c, int roomNumber, LocalDate checkIn, LocalDate checkOut)
    80	            throws SQLException {
    81	        try (PreparedStatement st = c.prepareStatement(
    82	                "select 1 from reservations where room_number = ? and status <> 'CANCELLED' "
    83	                        + "and check_in < ? and check_out > ? limit 1")) {
    84	            st.setInt(1, roomNumber);
    85	            st.setObject(2, checkOut);
    86	            st.setObject(3, checkIn);
    87	            try (ResultSet rs = st.executeQuery()) {
    88	                return rs.next();
    89	            }
    90	        }
    91	    }
    92	
    93	    public List<Reservation> paidOccupying(Connection c, LocalDate night) throws SQLException {
    94	        String statuses = ReservationStatus.paidOnes().stream()
    95	                .map(s -> "'" + s.name() + "'").collect(Collectors.joining(", "));
    96	        return query(c, "select * from reservations where status in (" + statuses + ") "
    97	                + "and check_in <= ? and check_out > ? order by room_number, id", st -> {
    98	            st.setObject(1, night);
    99	            st.setObject(2, night);
   100	        });
   101	    }
   102	
   103	    public List<Reservation> startingIn(Connection c, YearMonth month) throws SQLException {
   104	        return query(c, "select * from reservations where check_in >= ? and check_in <= ? "
   105	                + "order by check_in, id", st -> {
   106	            st.setObject(1, month.atDay(1));
   107	            st.setObject(2, month.atEndOfMonth());
   108	        });
   109	    }
   110	
   111	    @FunctionalInterface
   112	    private interface Binder {
   113	        void bind(PreparedStatement st) throws SQLException;
   114	    }
   115	
   116	    private List<Reservation> query(Connection c, String sql, Binder binder) throws SQLException {
   117	        try (PreparedStatement st = c.prepareStatement(sql)) {
   118	            binder.bind(st);
   119	            try (ResultSet rs = st.executeQuery()) {
   120	                List<Reservation> result = new ArrayList<>();
   121	                while (rs.next()) {
   122	                    result.add(read(rs));
   123	                }
   124	                return result;
   125	            }
   126	        }
   127	    }
   128	
   129	    private Reservation read(ResultSet rs) throws SQLException {
   130	        Map<String, String> given = new HashMap<>();
   131	        for (String f : IdentityKinds.allFields()) {
   132	            given.put(f, rs.getString(f));
   133	        }
   134	        Identity identity = IdentityKinds.from(given)
   135	                .orElseThrow(() -> new IllegalStateException("Identificação inválida no banco"));
   136	        Quote quote = new Quote(rs.getInt("nights"), rs.getBigDecimal("subtotal"),
   137	                rs.getBigDecimal("discount"), rs.getBigDecimal("total"));
   138	        return new Reservation(rs.getLong("id"),
   139	                Rooms.find(rs.getInt("room_number")).orElseThrow(),
   140	                rs.getString("guest_name"), rs.getString("guest_email"), identity,
   141	                rs.getObject("check_in", LocalDate.class), rs.getObject("check_out", LocalDate.class),
   142	                rs.getInt("guests"), RatePlan.valueOf(rs.getString("rate_plan")), quote,
   143	                ReservationStatus.valueOf(rs.getString("status")),
   144	                rs.getBigDecimal("amount_paid"), rs.getBigDecimal("refund"));
   145	    }
   146	}
